for index, (tag, prompt, opts, answer, reason) in enumerate(DATA, 1):
    record = json.loads((OUT / f'question-science-content-nc-iv-5-{index}.json').read_text())
    correct_index = opts.index(answer)
    target = TARGET_ANSWERS[index - 1]
    distractors = [text for option_index, text in enumerate(opts) if option_index != correct_index]
    position = ord(target) - 65
    arranged = distractors[:position] + [answer] + distractors[position:]
    steps = [f'讀題定位：圈出「{tag}」及題目要求判斷的效益、限制或證據。', f'建立判準：{reason}', f'核對答案：選項 {target}「{answer}」符合本題判準。', '排除誘答：檢查是否漏算生命週期、系統條件、風險、不確定性或受影響群體。', f'最後回查：確認「{answer}」能由題目給定的比較範圍支持。']
    record.update({'prompt': prompt, 'options': [{'id': chr(65 + i), 'text': text} for i, text in enumerate(arranged)], 'answer': {'value': target, 'explanation': reason + f' 正確答案為選項 {target}：「{answer}」。'}, 'solutionStrategy': '先界定技術提供的服務，再檢查資源條件、生命週期、系統限制與風險證據，避免只用單一宣稱下結論。', 'solutionSteps': steps, 'reviewStatus': 'draft', 'updatedAt': '2026-09-13', 'provenance': {**record.get('provenance', {}), 'sourceUrl': URL, 'sourceLocator': '公立國中段考自然科；研究新興能源科技原理、效益、限制、生命週期與風險溝通的能力方向。', 'authoringNote': '依官方課綱 KG 與公立國中公開試題能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}})
    record['examPatternRefs'] = [{'url': URL, 'title': '公立國中段考自然科；僅研究題型與能力方向，未複製原題。', 'year': '114', 'subject': 'science', 'locator': '新興能源科技原理、效益與風險', 'observedPattern': '能力方向研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'}]
    (OUT / f'question-science-content-nc-iv-5-{index}.json').write_text(json.dumps(record, ensure_ascii=False, indent=2) + '\n')
print('rewrote', len(DATA), 'questions')
